/**
 * Minimal markdown renderer for the extension.
 * Handles: headers, bold, italic, code blocks, inline code, links, lists, paragraphs.
 */
(function(global) {
  'use strict';

  function escapeHtml(text) {
    return text
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;');
  }

  function marked(src) {
    if (!src) return '';
    let html = '';
    const lines = src.split('\n');
    let i = 0;
    let inCodeBlock = false;
    let codeContent = '';
    let codeLang = '';

    while (i < lines.length) {
      const line = lines[i];

      // Fenced code blocks
      if (line.trim().startsWith('```')) {
        if (!inCodeBlock) {
          inCodeBlock = true;
          codeLang = line.trim().slice(3).trim();
          codeContent = '';
          i++;
          continue;
        } else {
          inCodeBlock = false;
          html += '<pre><code class="language-' + escapeHtml(codeLang) + '">' + escapeHtml(codeContent.replace(/\n$/, '')) + '</code></pre>\n';
          i++;
          continue;
        }
      }

      if (inCodeBlock) {
        codeContent += line + '\n';
        i++;
        continue;
      }

      // Empty line
      if (line.trim() === '') {
        i++;
        continue;
      }

      // Headers
      const headerMatch = line.match(/^(#{1,6})\s+(.+)/);
      if (headerMatch) {
        const level = headerMatch[1].length;
        html += '<h' + level + '>' + inline(headerMatch[2]) + '</h' + level + '>\n';
        i++;
        continue;
      }

      // Unordered list
      if (line.match(/^\s*[-*+]\s+/)) {
        html += '<ul>\n';
        while (i < lines.length && lines[i].match(/^\s*[-*+]\s+/)) {
          const item = lines[i].replace(/^\s*[-*+]\s+/, '');
          html += '<li>' + inline(item) + '</li>\n';
          i++;
        }
        html += '</ul>\n';
        continue;
      }

      // Ordered list
      if (line.match(/^\s*\d+\.\s+/)) {
        html += '<ol>\n';
        while (i < lines.length && lines[i].match(/^\s*\d+\.\s+/)) {
          const item = lines[i].replace(/^\s*\d+\.\s+/, '');
          html += '<li>' + inline(item) + '</li>\n';
          i++;
        }
        html += '</ol>\n';
        continue;
      }

      // Horizontal rule
      if (line.match(/^[-*_]{3,}\s*$/)) {
        html += '<hr>\n';
        i++;
        continue;
      }

      // Blockquote
      if (line.startsWith('>')) {
        let quoteContent = '';
        while (i < lines.length && lines[i].startsWith('>')) {
          quoteContent += lines[i].replace(/^>\s?/, '') + '\n';
          i++;
        }
        html += '<blockquote>' + marked(quoteContent) + '</blockquote>\n';
        continue;
      }

      // Paragraph
      html += '<p>' + inline(line) + '</p>\n';
      i++;
    }

    // Close unclosed code block
    if (inCodeBlock) {
      html += '<pre><code>' + escapeHtml(codeContent) + '</code></pre>\n';
    }

    return html;
  }

  function inline(text) {
    // Inline code
    text = text.replace(/`([^`]+)`/g, '<code>$1</code>');
    // Bold
    text = text.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
    text = text.replace(/__(.+?)__/g, '<strong>$1</strong>');
    // Italic
    text = text.replace(/\*(.+?)\*/g, '<em>$1</em>');
    text = text.replace(/_(.+?)_/g, '<em>$1</em>');
    // Strikethrough
    text = text.replace(/~~(.+?)~~/g, '<del>$1</del>');
    // Links
    text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
    // Images
    text = text.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1" style="max-width:100%">');

    return text;
  }

  marked.parse = marked;
  global.marked = marked;
})(typeof window !== 'undefined' ? window : this);
